import { useState, useCallback, memo, useEffect, useRef } from 'react';
import '../styles/searchForm.css';

const SearchForm = memo(({ 
  onSearch, 
  initialValues,
  wide, 
  isLoading
}) => {
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [date, setDate] = useState('');
  const [showFromSuggestions, setShowFromSuggestions] = useState(false);
  const [showToSuggestions, setShowToSuggestions] = useState(false);
  const [fromSuggestions, setFromSuggestions] = useState([]);
  const [toSuggestions, setToSuggestions] = useState([]);
  const [isFetchingCities, setIsFetchingCities] = useState(false);
  const [error, setError] = useState(null);
  const fromInputRef = useRef(null);
  const toInputRef = useRef(null);

  useEffect(() => {
    setFrom(initialValues.from || '');
    setTo(initialValues.to || '');
    setDate(initialValues.date || '');
  }, [initialValues]);

  const handleSubmit = useCallback((e) => {
    e.preventDefault();
    if (!isLoading && from && to) {
      onSearch({ from, to, date });
    }
  }, [from, to, date, onSearch, isLoading]);

  // Функция для поиска городов по первым буквам
  const searchCities = useCallback(async (query) => {
    if (!query || query.length < 1) return [];
    
    try {
      setIsFetchingCities(true);
      setError(null);
      
      // Здесь должен быть ваш API запрос
      // Для демонстрации используем статичный список
      const allCities = [
        'Москва', 'Санкт-Петербург', 'Казань', 'Новосибирск',
        'Екатеринбург', 'Краснодар', 'Сочи', 'Нижний Новгород', 'Стерлитамак'
      ];
      
      // Фильтрация по началу строки (первым буквам)
      const filtered = allCities.filter(city => 
        city.toLowerCase().startsWith(query.toLowerCase())
      );
      
      // Имитация задержки API
      await new Promise(resolve => setTimeout(resolve, 300));
      
      return filtered.map(city => ({ name: city }));
    } catch (err) {
      console.error('Ошибка при загрузке городов:', err);
      setError('Не удалось загрузить список городов');
      return [];
    } finally {
      setIsFetchingCities(false);
    }
  }, []);

  // Дебаунс для оптимизации запросов
  const debounce = (func, delay) => {
    let timer;
    return function(...args) {
      clearTimeout(timer);
      timer = setTimeout(() => func.apply(this, args), delay);
    };
  };

  const debouncedSearch = useCallback(debounce(async (query, setSuggestions) => {
    const results = await searchCities(query);
    setSuggestions(results);
  }, 300), [searchCities]);

  const handleFromChange = useCallback((e) => {
    const value = e.target.value;
    setFrom(value);
    debouncedSearch(value, setFromSuggestions);
  }, [debouncedSearch]);

  const handleToChange = useCallback((e) => {
    const value = e.target.value;
    setTo(value);
    debouncedSearch(value, setToSuggestions);
  }, [debouncedSearch]);

  const handleDateChange = useCallback((e) => {
    setDate(e.target.value);
  }, []);

  const selectCity = useCallback((setCity, setShowSuggestions, cityName) => {
    setCity(cityName);
    setShowSuggestions(false);
  }, []);

  // Закрытие списка при клике вне инпута
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (fromInputRef.current && !fromInputRef.current.contains(e.target)) {
        setShowFromSuggestions(false);
      }
      if (toInputRef.current && !toInputRef.current.contains(e.target)) {
        setShowToSuggestions(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className="search-form-container">
      <form onSubmit={handleSubmit} className={`search-form ${wide ? 'wide' : ''}`}>
        {wide && <h2 className="form-title">Поиск билетов</h2>}
        
        {error && (
          <div className="error-message">
            {error}
            <button onClick={() => setError(null)}>×</button>
          </div>
        )}
        
        <div className="form-grid">
          <div className="input-group">
            <label htmlFor="from">Откуда</label>
            <div className="input-wrapper" ref={fromInputRef}>
              <input
                id="from"
                name="from"
                value={from}
                onChange={handleFromChange}
                onFocus={() => {
                  setShowFromSuggestions(true);
                  if (from) debouncedSearch(from, setFromSuggestions);
                }}
                placeholder="Город отправления"
                autoComplete="off"
                disabled={isFetchingCities}
              />
              {showFromSuggestions && (
                <ul className="suggestions">
                  {isFetchingCities ? (
                    <li className="loading">Загрузка...</li>
                  ) : fromSuggestions.length > 0 ? (
                    fromSuggestions.map(city => (
                      <li 
                        key={city.name} 
                        onClick={() => selectCity(setFrom, setShowFromSuggestions, city.name)}
                      >
                        {city.name}
                      </li>
                    ))
                  ) : (
                    <li className="no-results">Ничего не найдено</li>
                  )}
                </ul>
              )}
            </div>
          </div>

          <div className="input-group">
            <label htmlFor="to">Куда</label>
            <div className="input-wrapper" ref={toInputRef}>
              <input
                id="to"
                name="to"
                value={to}
                onChange={handleToChange}
                onFocus={() => {
                  setShowToSuggestions(true);
                  if (to) debouncedSearch(to, setToSuggestions);
                }}
                placeholder="Город прибытия"
                autoComplete="off"
                disabled={isFetchingCities}
              />
              {showToSuggestions && (
                <ul className="suggestions">
                  {isFetchingCities ? (
                    <li className="loading">Загрузка...</li>
                  ) : toSuggestions.length > 0 ? (
                    toSuggestions.map(city => (
                      <li 
                        key={city.name} 
                        onClick={() => selectCity(setTo, setShowToSuggestions, city.name)}
                      >
                        {city.name}
                      </li>
                    ))
                  ) : (
                    <li className="no-results">Ничего не найдено</li>
                  )}
                </ul>
              )}
            </div>
          </div>

          <div className="input-group date-group">
            <label htmlFor="date">Дата (необязательно)</label>
            <div className="input-wrapper">
              <input
                id="date"
                name="date"
                type="date"
                value={date}
                onChange={handleDateChange}
                min={new Date().toISOString().split('T')[0]}
              />
            </div>
          </div>
        </div>

        <div className="search-button-container">
          <button 
            type="submit" 
            className="search-button"
            disabled={!from || !to || isLoading || isFetchingCities}
          >
            {isLoading ? 'Загрузка...' : 'Найти билеты'}
          </button>
        </div>
      </form>
    </div>
  );
});

export default SearchForm;
